import math

def dcg(grades):
    return sum((2**g - 1) / math.log2(rank + 1)
               for rank, g in enumerate(grades, 1))

def ndcg(grades):
    ideal = dcg(sorted(grades, reverse=True))
    return dcg(grades) / ideal if ideal else 0.0

def recall_at_k(ranking, relevant, k):
    relevant = set(relevant)
    if not relevant: return 0.0
    return len(set(ranking[:k]) & relevant) / len(relevant)

assert math.isclose(dcg([2, 0, 3]), 6.5)
assert math.isclose(ndcg([2, 0, 3]), 6.5/(7+3/math.log2(3)))
assert recall_at_k(['B','C','A','D'], {'A','C','E'}, 2) == 1/3
assert recall_at_k(['C','C','A'], {'A','C','E'}, 3) == 2/3
assert ndcg([0, 0]) == 0.0
print('retrieval metrics checks passed')

sources = {
    'S1': {'renewal_date':'2026-07-01'},
    'S2': {'annual_fee_usd':24000, 'discount_policy':'approval_required'}
}

def audit(claim, documents):
    citation = claim['source']
    if citation not in documents: return 'missing_citation'
    value = documents[citation].get(claim['field'])
    if value is None: return 'not_enough_information'
    return 'supported' if value == claim['value'] else 'contradicted'

cases = [
  ({'source':'S1','field':'renewal_date','value':'2026-07-01'}, 'supported'),
  ({'source':'S2','field':'annual_fee_usd','value':24000}, 'supported'),
  ({'source':'S2','field':'automatic_discount_pct','value':10}, 'not_enough_information'),
  ({'source':'S1','field':'renewal_date','value':'2026-08-01'}, 'contradicted'),
  ({'source':'S3','field':'annual_fee_usd','value':24000}, 'missing_citation'),
]
for claim, expected in cases:
    assert audit(claim, sources) == expected, (claim, expected)
print('grounding fixture checks passed')
